package com.tajlpawa.ageofexpansion.gametest;
import com.tajlpawa.ageofexpansion.image.client.*;
import java.awt.image.BufferedImage;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.GameTestHolder;
@GameTestHolder("ageofexpansion")
public final class PaintSelectionTests {
    @GameTestGenerator public static Collection<TestFunction> tests(){var all=new ArrayList<TestFunction>();add(all,"geometry",PaintSelectionTests::geometry);add(all,"selection",PaintSelectionTests::selection);add(all,"fill",PaintSelectionTests::fill);add(all,"move",PaintSelectionTests::move);add(all,"crop_edges",PaintSelectionTests::cropEdges);add(all,"history",PaintSelectionTests::history);add(all,"large",PaintSelectionTests::large);return all;}
    private interface Test{void run(GameTestHelper h)throws Exception;}
    private static void add(List<TestFunction> all,String name,Test test){all.add(new TestFunction("ageofexpansion:paint","ageofexpansion:paint_"+name,"ageofexpansion:module_empty",1000,0,true,h->{try{test.run(h);h.succeed();}catch(Exception e){throw new RuntimeException(e);}}));}
    private static PaintRegion.Point p(double x,double y){return new PaintRegion.Point(x,y);}
    private static BitSet rect(int w,int h,int x0,int y0,int x1,int y1){return PaintRegion.rectangle(w,h,p(x0,y0),p(x1,y1));}
    private static PaintCanvas canvas(){return new PaintCanvas(new BufferedImage(16,16,BufferedImage.TYPE_INT_ARGB),32,1);}
    private static void geometry(GameTestHelper h){h.assertTrue(rect(16,16,7,6,3,2).cardinality()==25,"Reverse rectangle");h.assertTrue(rect(16,16,3,3,3,3).cardinality()==1,"Single pixel selection");h.assertTrue(rect(16,16,-8,-8,3,3).cardinality()==16,"Canvas clipping");
        for(var points:List.of(List.of(p(1,1),p(9,1),p(9,9),p(1,9)),List.of(p(1,1),p(10,10),p(1,10),p(10,1)),List.of(p(-10,2),p(22,3),p(2,19)))){var path=new java.awt.geom.Path2D.Double(java.awt.geom.Path2D.WIND_EVEN_ODD);path.moveTo(points.getFirst().x(),points.getFirst().y());for(var v:points)path.lineTo(v.x(),v.y());path.closePath();var region=PaintRegion.polygon(16,16,points);for(int y=0;y<16;y++)for(int x=0;x<16;x++)h.assertTrue(region.get(y*16+x)==path.contains(x+.5,y+.5),"Even-odd reference including self intersection");}h.assertTrue(PaintRegion.polygon(16,16,List.of(p(1,1),p(2,2))).isEmpty(),"Line has no area");}
    private static void selection(GameTestHelper h)throws Exception{try(var c=canvas()){var a=rect(16,16,1,1,4,4);var b=rect(16,16,3,3,6,6);c.select(a,false);c.select(b,false);h.assertTrue(c.selection().cardinality()==28,"Union deduplicates overlap");c.select(b,true);h.assertTrue(c.selection().cardinality()==12,"Clear subtracts only mask");c.fill(rect(16,16,0,0,15,15),0xff0000,100,false);h.assertTrue(c.image.getRGB(1,1)==0xffff0000&&c.image.getRGB(5,5)==0,"Fill clipped to selection");c.select(c.selection(),true);c.begin(8,8,512,0xffffff,100,false);c.end();h.assertTrue(c.hasSelection()&&c.selection().isEmpty()&&c.image.getRGB(8,8)==0,"Empty mask blocks drawing");c.clearSelection();c.begin(8,8,1,0xffffff,100,false);c.end();h.assertTrue(c.image.getRGB(8,8)==-1,"Deselect restores painting");}}
    private static void fill(GameTestHelper h)throws Exception{try(var c=canvas()){var mask=PaintRegion.polygon(16,16,List.of(p(2,2),p(12,2),p(8,12)));c.fill(mask,0x336699,50,false);int pixel=c.image.getRGB(8,4);h.assertTrue(pixel>>>24==128,"Opacity once per leaf");c.fill(mask,0,50,true);h.assertTrue(c.image.getRGB(8,4)>>>24==64,"Clear honours opacity");c.undo();h.assertTrue(c.image.getRGB(8,4)==pixel,"Undo restores alpha");c.fill(mask,0,100,true);h.assertTrue(c.image.getRGB(8,4)>>>24==0,"Full erase");}}
    private static void move(GameTestHelper h)throws Exception{var image=new BufferedImage(8,4,2);image.setRGB(1,1,0xffff0000);image.setRGB(2,1,0x8000ff00);image.setRGB(3,1,0xff0000ff);try(var c=new PaintCanvas(image,32,1)){c.select(rect(8,4,1,1,2,1),false);var before=c.image.getRGB(0,0,8,4,null,0,8);var move=c.prepareMove();c.move(move,1,0);h.assertTrue(c.image.getRGB(1,1)==0&&c.image.getRGB(2,1)==0xffff0000,"Overlap uses source snapshot");h.assertTrue(c.image.getRGB(3,1)==PaintCanvas.over(0x8000ff00,0xff0000ff),"Composite once");h.assertTrue(c.selection().get(11)&&!c.selection().get(9),"Mask follows pixels");c.undo();h.assertTrue(Arrays.equals(before,c.image.getRGB(0,0,8,4,null,0,8))&&c.selection().equals(move.mask()),"Undo restores mask and pixels");c.move(move,-2,0);h.assertTrue(c.image.getRGB(0,1)==0x8000ff00&&c.image.getRGB(1,1)==0&&c.image.getRGB(2,1)==0&&c.selection().cardinality()==1,"Out-of-canvas move clips and deletes the overhanging red pixel");c.undo();h.assertTrue(Arrays.equals(before,c.image.getRGB(0,0,8,4,null,0,8)),"Undo restores cropped pixels");c.move(move,999,-999);h.assertTrue(c.selection().isEmpty()&&c.image.getRGB(1,1)==0&&c.image.getRGB(2,1)==0,"Fully outside move deletes all selected content");c.undo();h.assertTrue(Arrays.equals(before,c.image.getRGB(0,0,8,4,null,0,8)),"Fully clipped move undo is complete");}}
    private static void cropEdges(GameTestHelper h)throws Exception{for(int[] delta:new int[][]{{-2,0,2},{6,0,2},{0,-2,2},{0,2,2},{-2,-2,1},{100,100,0}}){var image=new BufferedImage(8,4,2);image.setRGB(1,1,0xffff0000);image.setRGB(2,2,0x8000ff00);try(var c=new PaintCanvas(image,32,1)){var region=rect(8,4,1,1,2,2);c.select(region,false);var pixels=c.image.getRGB(0,0,8,4,null,0,8);c.move(c.prepareMove(),delta[0],delta[1]);h.assertTrue(c.hasSelection()&&c.selection().cardinality()==delta[2],"Crop handles all four edges, corner, and fully outside selection");c.undo();h.assertTrue(region.equals(c.selection())&&Arrays.equals(pixels,c.image.getRGB(0,0,8,4,null,0,8)),"Every crop direction can be undone exactly");}}}
    private static void history(GameTestHelper h)throws Exception{try(var c=canvas()){c.select(rect(16,16,1,1,2,2),false);long revision=c.imageRevision();c.clearSelection();c.undo();h.assertTrue(c.hasSelection()&&!c.lastUndoPixels()&&c.imageRevision()==revision,"Mask undo does not dirty image");int count=c.undoCount();c.select(c.selection(),false);c.fill(c.selection(),0,0,false);h.assertTrue(c.undoCount()==count,"No-op history suppressed");c.begin(1,1,1,0xff0000,100,false);c.cancel();h.assertTrue(c.image.getRGB(1,1)==0&&c.undoCount()==count,"Cancel restores stroke");}try(var c=new PaintCanvas(new BufferedImage(16,16,2),0)){c.select(rect(16,16,1,1,2,2),false);c.fill(c.selection(),0xff0000,100,false);h.assertTrue(!c.undo()&&c.undoCount()==0,"Undo disabled");}}
    private static void large(GameTestHelper h)throws Exception{long start=System.nanoTime();try(var c=new PaintCanvas(new BufferedImage(2048,2048,2),2,1024)){var mask=PaintRegion.polygon(2048,2048,List.of(p(0,0),p(2048,0),p(2048,2048),p(0,2048)));h.assertTrue(mask.cardinality()==2048*2048,"Maximum mask complete");c.select(mask,false);c.fill(mask,0x123456,100,false);c.undo();h.assertTrue(c.image.getRGB(2047,2047)==0&&c.hasSelection(),"Large undo spill restores corner");}com.tajlpawa.ageofexpansion.AgeofExpansion.LOGGER.info("PAINT_SELECTION_LARGE_PASSED elapsed_ms={}",(System.nanoTime()-start)/1000000);}
}
